def infinityBadSets (S : Set (Set ℕ)) (φ : lp (fun _ : ℕ => 𝕜) ∞ →L[𝕜] 𝕜) (ε : ℝ) :
    Set (Set ℕ) :=
  {A ∈ S | ∃ x : lp (fun _ : ℕ => 𝕜) ∞,
    (∀ n ∉ A, x n = 0) ∧ ‖x‖ ≤ 1 ∧ ε < ‖φ x‖}

